**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ifstream plik("napisy.txt");
    string s;
    string maxNapis;
    int maxCyfr = -1;
    while (plik >> s) {
        int male = 0, duze = 0, cyfry = 0;
        for (char c : s) {
            if (islower(c)) male++;
            else if (isupper(c)) duze++;
            else if (isdigit(c)) cyfry++;
        }
        cout << s << ": male=" << male << ", duze=" << duze << ", cyfry=" << cyfry << endl;
        if (cyfry > maxCyfr) {
            maxCyfr = cyfry;
            maxNapis = s;
        }
    }
    cout << "Najwiecej cyfr: " << maxNapis << " (" << maxCyfr << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Funkcje `islower()`, `isupper()`, `isdigit()` z `<cctype>` klasyfikuja znaki. Iterujemy po kazdym znaku napisu i zwiekszamy odpowiedni licznik.

